import React, { useState } from 'react';
import { View, Text, StyleSheet, TextInput, Button, FlatList, Alert } from 'react-native';
import { fetchWithAuth } from '../lib/api';

export default function RenterReviewScreen() {
  const [renterEmail, setRenterEmail] = useState('');
  const [reviews, setReviews] = useState([]);
  const [rating, setRating] = useState('5');
  const [comment, setComment] = useState('');

  const loadReviews = async () => {
    if (!renterEmail) return Alert.alert('Anna vuokraajan sähköposti.');
    try {
      const res = await fetchWithAuth(`/api/reviews?targetType=renter&targetId=${encodeURIComponent(renterEmail)}`);
      const data = await res.json();
      setReviews(data);
    } catch (e) {
      Alert.alert('Arvostelujen lataus epäonnistui.');
    }
  };

  const submitReview = async () => {
    if (!renterEmail) return Alert.alert('Anna vuokraajan sähköposti.');
    if (!rating) return Alert.alert('Anna arvosana.');

    try {
      const res = await fetchWithAuth('/api/reviews', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ targetType: 'renter', targetId: renterEmail, rating: Number(rating), comment })
      });
      if (res.status === 401) {
        return Alert.alert('Kirjaudu sisään ensin.');
      }
      await res.json();
      setComment('');
      setRating('5');
      Alert.alert('Arvostelu tallennettu');
      loadReviews();
    } catch (e) {
      Alert.alert('Arvostelun luonti epäonnistui');
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Vuokraajan arvostelu</Text>
      <TextInput
        style={styles.input}
        placeholder="Vuokraajan sähköposti"
        value={renterEmail}
        onChangeText={setRenterEmail}
        keyboardType="email-address"
      />
      <Button title="Lataa arvostelut" onPress={loadReviews} />
      <Text style={styles.section}>Arvostelut</Text>
      <FlatList
        data={reviews}
        keyExtractor={(item) => item.id}
        ListEmptyComponent={<Text>Ei arvosteluja.</Text>}
        renderItem={({ item }) => (
          <View style={styles.card}>
            <Text style={styles.reviewer}>{item.reviewer}</Text>
            <Text style={styles.rating}>Arvio: {item.rating}/5</Text>
            <Text>{item.comment}</Text>
          </View>
        )}
      />
      <Text style={styles.section}>Lisää arvostelu</Text>
      <TextInput
        style={styles.input}
        placeholder="Arvostelusi"
        value={comment}
        onChangeText={setComment}
        multiline
      />
      <TextInput
        style={styles.input}
        placeholder="Arvosana 1-5"
        value={rating}
        onChangeText={setRating}
        keyboardType="numeric"
      />
      <Button title="Lähetä vuokraaja-arvostelu" onPress={submitReview} />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 16 },
  title: { fontSize: 20, fontWeight: '700', marginBottom: 12 },
  section: { fontSize: 16, fontWeight: '700', marginTop: 16, marginBottom: 8 },
  input: { borderWidth: 1, borderColor: '#ccc', padding: 10, borderRadius: 6, marginBottom: 12, minHeight: 44 },
  card: { padding: 12, borderWidth: 1, borderColor: '#eee', borderRadius: 8, marginBottom: 12 },
  reviewer: { fontWeight: '700', marginBottom: 4 },
  rating: { marginBottom: 6 }
});
